class SmoothWRR:
    def __init__(self, weights: dict[str, int]):
        assert all(w > 0 for w in weights.values())
        self.weights = weights
        self.current = {k: 0 for k in weights}
        self.total = sum(weights.values())

    def pick(self) -> str:
        # WHY deficit, not a precomputed table: O(N) per pick,
        # O(N) state, no expansion of S slots, naturally interleaved.
        best = None
        for node, w in self.weights.items():
            self.current[node] += w
            if best is None or self.current[node] > self.current[best]:
                best = node
        self.current[best] -= self.total
        return best

# weights 3,2,1 -> A B A C B A | A B A C B A ...
# classical table would emit A A A B B C -> bursty for A.
bal = SmoothWRR({"A": 3, "B": 2, "C": 1})
print([bal.pick() for _ in range(12)])
